/* Piksel Futbol — TEK DOSYA çevrimiçi sunucu. Çalıştır: node server.js */
const defs = {}, cache = {};
function R(n) { if (n.startsWith('src/')) { if (cache[n]) return cache[n].exports; const m = { exports: {} }; cache[n] = m; defs[n](m, m.exports, R); return m.exports; } return require(n); }
const HTML_B64 = '';
defs["src/core/ach.js"]=function(module,exports,require){
'use strict';
/* Oyuncu başarımları: kalıcı saklama gerekmez, mevcut istatistiklerden hesaplanır (sunucu ve istemci aynı fonksiyonu kullanır).
   Her başarımın 4 kademesi vardır: Bronz, Gümüş, Altın, Elmas. */
const TIERS = ['Bronz', 'Gümüş', 'Altın', 'Elmas'];
const CATS = [['all', 'Tümü'], ['atk', 'Hücum'], ['def', 'Savunma'], ['match', 'Maç'], ['prog', 'Gelişim']];
const LIST = [
  { id: 'g', c: 'atk', ic: '⚽', name: 'Golcü', desc: 'Gol at', k: 'g', t: [10, 50, 200, 1000] },
  { id: 'a', c: 'atk', ic: '🎯', name: 'Asist Ustası', desc: 'Asist yap', k: 'a', t: [10, 50, 200, 1000] },
  { id: 'ga', c: 'atk', ic: '🔥', name: 'Gol Makinesi', desc: 'Gol + asist topla', k: 'ga', t: [25, 100, 400, 1500] },
  { id: 'mvp', c: 'atk', ic: '⭐', name: 'MVP', desc: 'Maçın oyuncusu seçil', k: 'mvp', t: [1, 10, 50, 200] },
  { id: 's', c: 'def', ic: '🧤', name: 'Duvar', desc: 'Kurtarış yap', k: 's', t: [20, 100, 500, 2000] },
  { id: 'cs', c: 'def', ic: '🛡', name: 'Kale Kilidi', desc: 'Gol yemeden bitir', k: 'cs', t: [5, 25, 100, 300] },
  { id: 'm', c: 'match', ic: '🏟', name: 'Sahaların Adamı', desc: 'Maç oyna', k: 'm', t: [10, 50, 250, 1000] },
  { id: 'w', c: 'match', ic: '🏆', name: 'Kazanan', desc: 'Maç kazan', k: 'w', t: [5, 25, 100, 500] },
  { id: 'd', c: 'match', ic: '🤝', name: 'Dengeci', desc: 'Berabere biten maç', k: 'd', t: [5, 25, 100, 300] },
  { id: 'rm', c: 'match', ic: '📊', name: 'Rank Savaşçısı', desc: 'Rank maçı oyna', k: 'rm', t: [10, 50, 200, 800] },
  { id: 'cm', c: 'match', ic: '⚔', name: 'Klan Savaşçısı', desc: 'Klan maçı oyna', k: 'cm', t: [5, 25, 100, 300] },
  { id: 'sm', c: 'match', ic: '🎮', name: 'Yalnız Kurt', desc: 'Tek başına maç oyna', k: 'sm', t: [10, 50, 200, 600] },
  { id: 'ws', c: 'match', ic: '⚡', name: 'Seri Galibiyet', desc: 'Üst üste galibiyet (en iyi seri)', k: 'ws', t: [3, 5, 10, 20] },
  { id: 'ls', c: 'prog', ic: '📅', name: 'Sadık Oyuncu', desc: 'Günlük giriş serisi', k: 'ls', t: [3, 7, 30, 100] },
  { id: 'peak', c: 'prog', ic: '👑', name: 'Kupa Avcısı', desc: 'En yüksek kupa', k: 'peak', t: [500, 1000, 2000, 3500] },
  { id: 'lvl', c: 'prog', ic: '📈', name: 'Yükselen Yıldız', desc: 'Seviyeye ulaş', k: 'lvl', t: [10, 50, 100, 200] },
  { id: 'sea', c: 'prog', ic: '🌟', name: 'Sezon Şampiyonu', desc: 'Sezonu ilk 3\'te bitir', k: 'sea', t: [1, 2, 4, 8] },
];
const RANKS = [[0, 'Çaylak'], [6, 'Amatör'], [16, 'Profesyonel'], [30, 'Usta'], [44, 'Efsane']];   // toplam kademe puanına göre unvan
// kaynak: { stats, peak, mmr, card:{lvl}, sea }
function compute(src) {
  const s = (src && src.stats) || {};
  return LIST.map((a) => {
    const v = a.k === 'ws' ? (src.wsb || 0) : a.k === 'ls' ? (src.lsb || 0) : a.k === 'ga' ? (s.g || 0) + (s.a || 0) : a.k === 'peak' ? Math.max(src.peak || 0, src.mmr || 0) : a.k === 'lvl' ? ((src.card && src.card.lvl) || 1) : a.k === 'sea' ? (src.sea || 0) : (s[a.k] || 0);
    let tier = 0; while (tier < 4 && v >= a.t[tier]) tier++;
    return { id: a.id, c: a.c, ic: a.ic, name: a.name, desc: a.desc, v, tier, next: tier < 4 ? a.t[tier] : 0, prev: tier ? a.t[tier - 1] : 0 };
  });
}
function summary(src) {
  const l = compute(src); let pts = 0, done = 0;
  for (const a of l) { pts += a.tier; if (a.tier === 4) done++; }
  let rank = RANKS[0][1]; for (const r of RANKS) if (pts >= r[0]) rank = r[1];
  return { list: l, pts, max: l.length * 4, done, rank };
}
module.exports = { LIST, TIERS, CATS, compute, summary };
};
defs["src/core/ai.js"]=function(module,exports,require){
'use strict';
/* Bot yapay zekâsı: her bot için p.in alanlarını (ax, ay, btn, act, charge) doldurur.
   Karar her 2 adımda bir verilir; ucuzdur, 10 bot ~20 Hz çalışır. */
const { PR, BR, BTN, FORMATIONS, PHASE, clamp } = require("src/core/consts.js");

function nearestOpp(sim, team, x, y) {
  let m = 1e9;
  for (const o of sim.players) {
    if (!o || o.team === team) continue;
    const dx = o.x - x, dy = o.y - y, d = dx * dx + dy * dy;
    if (d < m) m = d;
  }
  return Math.sqrt(m);
}

// p -> (tx,ty) doğrusunun rakiplerce kapatılıp kapatılmadığı
function laneBlocked(sim, p, tx, ty) {
  const dx = tx - p.x, dy = ty - p.y, dd = dx * dx + dy * dy || 1;
  for (const o of sim.players) {
    if (!o || o.team === p.team) continue;
    const ox = o.x - p.x, oy = o.y - p.y;
    const t = clamp((ox * dx + oy * dy) / dd, 0, 1);
    const ex = ox - dx * t, ey = oy - dy * t;
    if (ex * ex + ey * ey < 700) return true;
  }
  return false;
}

function bestMate(sim, p, dir, pressure) {
  let best = null, bs = 0.15;
  for (const t of sim.players) {
    if (!t || t.team !== p.team || t === p || (t.slot === 0 && !pressure)) continue;
    const dx = t.x - p.x, dy = t.y - p.y, d = Math.sqrt(dx * dx + dy * dy);
    if (d < 70 || d > 620 * sim.sc) continue;
    if (laneBlocked(sim, p, t.x, t.y)) continue;
    const open = Math.min(1, nearestOpp(sim, p.team, t.x, t.y) / 120);
    const sc = 0.5 * open + (dx * dir / 400) * (pressure ? 0.4 : 1) - d / 2000;
    if (sc > bs) { bs = sc; best = t; }
  }
  return best;
}

function think(sim, p) {
  const inp = p.in;
  if (sim.phase !== PHASE.PLAY) { inp.ax = 0; inp.ay = 0; inp.btn = 0; return; }
  const ai = p.ai || (p.ai = { ax: 0, ay: 0, btn: 0 });
  if ((sim.tick + p.i) % 4 === 0) decide(sim, p, ai);       // botlar daha geç tepki verir
  inp.ax = ai.ax * 0.9; inp.ay = ai.ay * 0.9; inp.btn = ai.btn;
}

function decide(sim, p, ai) {
  const b = sim.ball, pl = sim.players, n = sim.n, W = sim.W, H = sim.H, CY = sim.CY;
  const dir = p.team === 0 ? 1 : -1;
  const own = p.team === 0 ? 0 : W, opp = p.team === 0 ? W : 0;
  const f = FORMATIONS[n][p.slot];
  const dx = b.x - p.x, dy = b.y - p.y, dist = Math.sqrt(dx * dx + dy * dy);
  const inp = p.in;
  let tx = p.x, ty = p.y, sprint = false;
  const mateHas = b.owner >= 0 && pl[b.owner].team === p.team;
  const oppHas = b.owner >= 0 && !mateHas;

  if (p.slot === 0) {                         // ---- kaleci
    if (p.hold > 0) {
      ai.ax = 0; ai.ay = 0; ai.btn = 0; inp.ax = 0; inp.ay = 0;           // tutarken yerinde durur
      if (p.hold < 1.6) {
        const t = bestMate(sim, p, dir, false) || bestMate(sim, p, dir, true);
        let ax = dir, ay = (CY - p.y) / 400;
        if (t) { ax = t.x - p.x; ay = t.y - p.y; }
        const m = Math.hypot(ax, ay) || 1;
        inp.ax = ax / m; inp.ay = ay / m; ai.ax = inp.ax; ai.ay = inp.ay; ai.btn = 0;
        inp.act = 1;
      }
      return;
    }
    const gx = own + dir * (46 + clamp(dist * 0.06, 0, 40)), half = sim.GW / 2 * 0.75;
    ty = clamp(b.y, CY - half, CY + half);
    ty = CY + (ty - CY) * (sim.gkWeak ? 0.55 : 0.8);           // bot kaleci köşeyi tam kapatmaz
    const coming = (own - b.x) * b.vx > 0 && Math.abs(b.vx) > 60;
    if (coming) {
      const t = (gx - b.x) / b.vx;
      if (t > 0 && t < 0.9) { ty = clamp(b.y + b.vy * t, CY - half, CY + half); ty = CY + (ty - CY) * (sim.gkWeak ? 0.5 : 0.75) + (sim.rnd() - 0.5) * (sim.gkWeak ? 60 : 90); }
    }
    tx = gx;
    const inBox = Math.abs(b.x - own) < 230 * sim.sc && Math.abs(b.y - CY) < 260 * sim.sc;
    if (inBox && Math.hypot(b.vx, b.vy) < 225 && nearestOpp(sim, p.team, b.x, b.y) > dist - 15 && sim.rnd() < 0.4) { tx = b.x; ty = b.y; sprint = true; }
  } else if (sim.chaser[p.team] === p.i || dist < 55) {   // ---- topun peşindeki oyuncu
    if (dist < PR * p.d.reach + BR + 14) { kickDecision(sim, p, ai, dir, own, opp); return; }
    const lead = clamp(dist / 400, 0, 0.5);
    tx = b.x + b.vx * lead; ty = b.y + b.vy * lead;
    sprint = dist > 110 && p.stamina > 0.2;
    if (oppHas && dist < 44 && p.lcd <= 0 && sim.rnd() < 0.1 * p.d.tackle) {
      inp.ax = dx / (dist || 1); inp.ay = dy / (dist || 1); inp.act = 3;
    }
  } else {                                      // ---- yerleşme
    tx = own + dir * f.ax * W;
    ty = (p.team === 0 ? f.ay : 1 - f.ay) * H;
    tx += (b.x - tx) * 0.35; ty += (b.y - ty) * 0.25;
    const push = p.pos === 'FOR' || p.pos === 'KNT' ? 1 : p.pos === 'OS' ? 0.6 : 0.2;
    if (mateHas) tx += dir * 90 * push; else if (oppHas) tx -= dir * 60;
    if (p.pos === 'DEF') tx = dir > 0 ? Math.min(tx, b.x - 30) : Math.max(tx, b.x + 30);
    for (const t of pl) {
      if (!t || t.team !== p.team || t === p) continue;
      const ex = p.x - t.x, ey = p.y - t.y, d = Math.sqrt(ex * ex + ey * ey);
      if (d < 80 && d > 0.1) { tx += ex / d * (80 - d) * 0.6; ty += ey / d * (80 - d) * 0.6; }
    }
    tx = clamp(tx, PR, W - PR); ty = clamp(ty, PR, H - PR);
    sprint = Math.hypot(tx - p.x, ty - p.y) > 220 && p.stamina > 0.4;
  }
  const mx = tx - p.x, my = ty - p.y, md = Math.sqrt(mx * mx + my * my);
  if (md < 10) { ai.ax = 0; ai.ay = 0; }
  else { const s = Math.min(1, md / 50); ai.ax = mx / md * s; ai.ay = my / md * s; }
  ai.btn = 0;
}

// top ayağında: şut / pas / top sürme
function kickDecision(sim, p, ai, dir, own, opp) {
  const inp = p.in, n = sim.n, CY = sim.CY;
  const dg = Math.abs(opp - p.x);
  const pressure = nearestOpp(sim, p.team, p.x, p.y) < 70;
  const range = (230 + 2.2 * p.st[1]) * sim.sc;
  if (dg < range && Math.abs(p.y - CY) < sim.GW * 1.6 + dg * 0.5) {
    const ax = opp - p.x, ay = CY - p.y, m = Math.hypot(ax, ay) || 1;
    inp.ax = ax / m; inp.ay = ay / m; ai.ax = inp.ax; ai.ay = inp.ay;
    if (p.shotWait > sim.time) { ai.btn = 0; return; }
    p.shotWait = sim.time + 0.8 + sim.rnd() * 1.2;
    inp.act = 2; inp.charge = clamp(0.5 + dg / 700 + sim.rnd() * 0.2, 0, 1);
    return;
  }
  if (pressure && Math.abs(p.x - own) < 260 * sim.sc) {      // tehlike: uzaklaştır
    inp.ax = dir; inp.ay = (p.y < CY ? -0.5 : 0.5); ai.ax = inp.ax; ai.ay = inp.ay;
    inp.act = 2; inp.charge = 0.7;
    return;
  }
  const mate = bestMate(sim, p, dir, pressure);
  if (mate && (pressure || sim.rnd() < 0.12 || (mate.x - p.x) * dir > 250)) {
    const ax = mate.x - p.x, ay = mate.y - p.y, m = Math.hypot(ax, ay) || 1;
    inp.ax = ax / m; inp.ay = ay / m; ai.ax = inp.ax; ai.ay = inp.ay;
    inp.act = 1;
    return;
  }
  // kaleye doğru sür, yakındaki rakiplerden kaç
  let ax = opp - p.x, ay = CY - p.y;
  const m0 = Math.hypot(ax, ay) || 1; ax /= m0; ay /= m0;
  for (const o of sim.players) {
    if (!o || o.team === p.team) continue;
    const ex = p.x - o.x, ey = p.y - o.y, d = Math.sqrt(ex * ex + ey * ey);
    if (d < 110 && d > 0.1 && (o.x - p.x) * dir > -20) { ax += ex / d * (110 - d) / 60; ay += ey / d * (110 - d) / 60; }
  }
  const m = Math.hypot(ax, ay) || 1;
  ai.ax = ax / m; ai.ay = ay / m;
  ai.btn = 0;
  // yetenek: baskı altındaysa ve boş alan varsa çalım atar
  if (pressure && p.scd <= 0 && sim.rnd() < 0.05) inp.act = 3;
}

module.exports = { think };

};
defs["src/core/cards.js"]=function(module,exports,require){
'use strict';
/* Oyuncu kartı: istatistikler, reyting (OVR), kademe, seviye/XP, gelişim puanı (GP), Seviye Pass. */
const { POSITIONS, SKINS, HAIRS, KITS, STRIPES, HAIR_STYLES, KIT_REQ, STRIPE_REQ, HAIR_REQ, FACES, ACCS, BOOTS, BALLS, POSES, GOAL_FX, SHOT_FX, CARD_BG, TITLES, CELS, ITEMS, clamp, hash32 } = require("src/core/consts.js");

const KEYS = ['pac', 'sho', 'pas', 'dri', 'def', 'phy'];
const LABELS = {
  std: ['HIZ', 'ŞUT', 'PAS', 'DRİ', 'SAV', 'GÜÇ'],
  KL: ['REF', 'DAĞ', 'PAS', 'TUT', 'KRT', 'GÜÇ'],
};
const FULL = {
  std: ['Hız', 'Şut', 'Pas', 'Dribling', 'Savunma', 'Güç'],
  KL: ['Refleks', 'Dağıtım', 'Pas', 'Tutuş', 'Kurtarış', 'Güç'],
};
// mevkiye göre reyting ağırlıkları (toplam 1.0)
const WEIGHTS = {
  KL:  [0.10, 0.10, 0.15, 0.20, 0.35, 0.10],
  DEF: [0.15, 0.05, 0.15, 0.10, 0.40, 0.15],
  OS:  [0.12, 0.15, 0.30, 0.25, 0.10, 0.08],
  KNT: [0.30, 0.15, 0.15, 0.28, 0.02, 0.10],
  FOR: [0.20, 0.35, 0.10, 0.20, 0.02, 0.13],
};
const STYLES = {
  dengeli: { name: 'Dengeli', d: [3, 3, 3, 3, 3, 3] },
  hizli:   { name: 'Hızlı',   d: [9, 1, 0, 5, -3, -5] },
  teknik:  { name: 'Teknik',  d: [1, 2, 6, 9, 0, -6] },
  guclu:   { name: 'Güçlü',   d: [-6, 5, 0, 0, 4, 9] },
};
const TIERS = [
  { id: 'bronz', name: 'Bronz', min: 0 },
  { id: 'gumus', name: 'Gümüş', min: 65 },
  { id: 'altin', name: 'Altın', min: 75 },
  { id: 'elit', name: 'Elit', min: 85 },
];
const MAX_LEVEL = 200;
const GP_PER_LEVEL = 0;       // gelişim puanı kaldırıldı: istatistikler gol/asist/kurtarışla kendiliğinden artar
const START_OVR_MAX = 58;       // her seviye atlayışta kazanılan gelişim puanı
const STAT_MAX = 99;

function labelsFor(pos) { return pos === 'KL' ? LABELS.KL : LABELS.std; }
function fullLabelsFor(pos) { return pos === 'KL' ? FULL.KL : FULL.std; }

function overall(st, pos) {
  const w = WEIGHTS[pos] || WEIGHTS.OS;
  let s = 0;
  for (let i = 0; i < 6; i++) s += st[i] * w[i];
  return clamp(Math.round(s), 1, 99);
}

function tierOf(ovr) {
  let t = TIERS[0];
  for (const x of TIERS) if (ovr >= x.min) t = x;
  return t;
}

function makeStats(name, pos, style) {
  const w = WEIGHTS[pos];
  const maxw = Math.max(...w);
  const h = hash32(String(name).toLowerCase() + pos);
  const d = (STYLES[style] || STYLES.dengeli).d;
  const st = [];
  for (let i = 0; i < 6; i++) {
    const jitter = ((h >>> (i * 4)) & 7) - 3;
    st.push(clamp(Math.round(40 + 17 * (w[i] / maxw) + d[i] * 0.6 + jitter), 25, 99));
  }
  while (overall(st, pos) > START_OVR_MAX) { let k = 0; for (let i = 1; i < 6; i++) if (st[i] > st[k]) k = i; st[k]--; }
  return st;
}

// kart görünümündeki mağaza alanları: alan -> en büyük değer; değer > 0 ise ürün sahipliği gerekir
const LOOK_MAX = { fc: FACES.length - 1, ac: ACCS.length - 1, boots: BOOTS.length - 1, bl: BALLS.length - 1, gf: GOAL_FX.length - 1, sf: SHOT_FX.length - 1, cbg: CARD_BG.length - 1, pz: POSES.length - 1, ttl: TITLES.length - 1, cl: CELS.length - 1 };
const ID_BY_FIELD = {};
for (const it of ITEMS) if (it.field) (ID_BY_FIELD[it.field] || (ID_BY_FIELD[it.field] = {}))[it.val] = it.id;

// lvl verilirse henüz açılmamış forma/çizgi seçenekleri en baştakine döner; inv: sahip olunan mağaza ürünleri (id listesi)
function sanitizeLook(l, lvl, inv) {
  l = l || {};
  const lv = lvl == null ? 999 : lvl;
  const owns = (field, val) => !!(inv && inv.includes((ID_BY_FIELD[field] || {})[val]));
  const n = (v, max, def) => { v = Math.floor(Number(v)); return Number.isFinite(v) ? clamp(v, 0, max) : def; };
  let kit = n(l.kit, KITS.length - 1, 0), stripe = n(l.stripe, STRIPES.length - 1, 0), hs = n(l.hs, HAIR_STYLES.length - 1, 1);
  if (KIT_REQ[kit] >= 900 ? !owns('kit', kit) : KIT_REQ[kit] > lv) kit = 0;
  if (STRIPE_REQ[stripe] >= 900 ? !owns('stripe', stripe) : STRIPE_REQ[stripe] > lv) stripe = 0;
  if (HAIR_REQ[hs] >= 900 && !owns('hs', hs)) hs = 1;
  const out = {
    skin: n(l.skin, SKINS.length - 1, 1),
    hs, hc: n(l.hc, HAIRS.length - 1, 0),
    kit, stripe,
    no: clamp(Math.floor(Number(l.no)) || 10, 1, 99),
  };
  for (const f of Object.keys(LOOK_MAX)) { const v = n(l[f], LOOK_MAX[f], 0); out[f] = v > 0 && owns(f, v) ? v : 0; }
  return out;
}

function makeCard(name, pos, style, look) {
  if (!POSITIONS.includes(pos)) pos = 'OS';
  if (!STYLES[style]) style = 'dengeli';
  return { pos, style, look: sanitizeLook(look, 1), st: makeStats(name, pos, style), lvl: 1, xp: 0, pts: 0, claimed: [] };
}

function xpNeed(lvl) { return lvl <= 60 ? 60 + 25 * lvl : 1560 + (lvl - 60) * 6; }

// kartı değiştirir; atlanan seviye sayısını döndürür. Her seviye GP_PER_LEVEL gelişim puanı verir.
function addXp(card, xp) {
  let ups = 0;
  card.xp += Math.max(0, Math.floor(xp));
  while (card.lvl < MAX_LEVEL && card.xp >= xpNeed(card.lvl)) {
    card.xp -= xpNeed(card.lvl);
    card.lvl++;
    card.pts += GP_PER_LEVEL;
    ups++;
  }
  if (card.lvl >= MAX_LEVEL) card.xp = 0;
  return ups;
}

// ---- otomatik gelişim: maç performansı istatistikleri yükseltir ----
// kesirli birikim card.fr'de tutulur; tam sayıya ulaşan kısım stata eklenir. Döndürür: 6 elemanlı artış dizisi
const GROW = { goal: [0.15, 0.6, 0, 0.25, 0, 0], assist: [0.1, 0, 0.6, 0.3, 0, 0], save: [0, 0, 0, 0, 0.35, 0.05], cs: [0, 0, 0, 0, 0.3, 0.1], played: [0.05, 0.05, 0.05, 0.05, 0.05, 0.05] };
function growCard(card, goals, assists, saves, cs) {
  if (!Array.isArray(card.fr) || card.fr.length !== 6) card.fr = [0, 0, 0, 0, 0, 0];
  const gain = [0, 0, 0, 0, 0, 0];
  for (let i = 0; i < 6; i++) {
    card.fr[i] += GROW.played[i] + goals * GROW.goal[i] + assists * GROW.assist[i] + saves * GROW.save[i] + (cs ? GROW.cs[i] : 0);
    const whole = Math.floor(card.fr[i]);
    if (whole > 0) { const add = Math.min(whole, STAT_MAX - card.st[i]); card.st[i] += add; gain[i] = add; card.fr[i] -= whole; if (card.st[i] >= STAT_MAX) card.fr[i] = 0; }
  }
  return gain;
}

// ---- gelişim (stat yükseltme) ----
const upCost = (v) => (v >= 90 ? 3 : v >= 80 ? 2 : 1);

// d: 6 elemanlı artış dizisi. Başarılıysa kartı günceller. err: bad | max | none | pts
function applyUpgrade(card, d) {
  if (!Array.isArray(d) || d.length !== 6) return { ok: false, err: 'bad' };
  const add = d.map((x) => Math.floor(Number(x)));
  if (add.some((x) => !Number.isFinite(x) || x < 0 || x > 70)) return { ok: false, err: 'bad' };
  const st = card.st.slice();
  let spent = 0;
  for (let i = 0; i < 6; i++) {
    for (let k = 0; k < add[i]; k++) {
      if (st[i] >= STAT_MAX) return { ok: false, err: 'max' };
      spent += upCost(st[i]); st[i]++;
    }
  }
  if (!spent) return { ok: false, err: 'none' };
  if (spent > card.pts) return { ok: false, err: 'pts' };
  card.st = st; card.pts -= spent;
  return { ok: true, spent };
}

// ---- Seviye Pass ----
// Her seviye atlayışta otomatik +GP_PER_LEVEL; 5. ve 10. katlarda ayrıca alınabilir bonus; belirli seviyelerde forma/çizgi açılır.
function passReward(lvl) {
  const unlock = [];
  KIT_REQ.forEach((r, i) => { if (r === lvl && lvl > 0) unlock.push({ type: 'kit', i }); });
  STRIPE_REQ.forEach((r, i) => { if (r === lvl && lvl > 0) unlock.push({ type: 'stripe', i }); });
  const m5 = lvl % 5 === 0;
  return { lvl, auto: 0, bonus: m5 ? (lvl % 10 === 0 ? 10 : 5) : 0, unlock,
    gold: m5 ? lvl * 3 : 0, gems: lvl % 10 === 0 ? Math.round(lvl / 10 * 2) : 0, item: PASS_ITEMS[lvl] || null };
}
// Seviye Pass ürün ödülleri (mağaza ürün kimlikleri); 60'a kadar her 5. seviyede, sonrasında her 10. seviyede bir ürün
const PASS_ITEMS = { 5: 'boot3', 10: 'ball1', 15: 'turf1', 20: 'post1', 25: 'ttl2', 30: 'sfx1', 35: 'board1', 40: 'hs6', 45: 'gfx1', 50: 'cbg1', 55: 'boot2', 60: 'ttl8' };
{
  const used = new Set(Object.values(PASS_ITEMS));
  const pool = ITEMS.filter((it) => ['cbg', 'ttl', 'cel', 'gfx', 'sfx', 'boot', 'ball'].includes(it.cat) && !used.has(it.id));
  let pi = 0;
  for (let l = 70; l <= 200 && pi < pool.length; l += 10) PASS_ITEMS[l] = pool[pi++].id;
}

// alınabilir bonus seviyeleri (ulaşılmış, henüz alınmamış)
function claimable(card) {
  const out = [];
  for (let l = 1; l <= card.lvl; l++) if (passReward(l).bonus && !card.claimed.includes(l)) out.push(l);
  return out;
}

// lvl verilirse yalnızca onu, verilmezse hepsini alır; kazanılan GP'yi döndürür
function claimPass(card, lvl) {
  let gp = 0, gold = 0, gems = 0; const items = [];
  for (const l of claimable(card)) {
    if (lvl != null && l !== lvl) continue;
    const r = passReward(l);
    card.claimed.push(l); gp += 0; gold += r.gold; gems += r.gems; if (r.item) items.push(r.item);
  }
  card.pts += gp;
  return { gp, gold, gems, items };
}

// istemciye / diğer oyunculara gösterilen kart görünümü
function cardView(name, card) {
  const ovr = overall(card.st, card.pos);
  return { name, pos: card.pos, ovr, tier: tierOf(ovr).id, st: card.st.slice(), look: card.look, lvl: card.lvl, xp: card.xp, next: xpNeed(card.lvl) };
}

// Transfer Pazarı değeri (oyun içi para birimi yok; yalnızca karşılaştırma içindir)
function marketValue(ovr, lvl, stats) {
  const s = stats || {};
  const base = Math.pow(Math.max(ovr - 35, 1), 2) * 0.9;
  return Math.round(base + lvl * 25 + (s.g || 0) * 6 + (s.a || 0) * 4 + (s.cs || 0) * 3) * 100;
}

// kart istatistiklerinden oyun içi çarpanlar (sunucu, bot ve istemci tahmini aynı fonksiyonu kullanır)
function derive(st, pos) {
  const f = (i) => st[i] / 99;
  return {
    spd: (0.92 + 0.20 * f(0)) * (pos === 'KL' ? 1.12 : 1),
    shotMul: 0.80 + 0.30 * f(1),
    shotErr: 0.16 - 0.13 * f(1),
    passMul: 0.90 + 0.20 * f(2),
    passErr: 0.12 - 0.10 * f(2),
    ctl: 0.7 + 0.6 * f(3),
    tackle: 0.8 + 0.5 * f(4),
    mass: 1 + 0.8 * f(5),
    stam: 1.25 - 0.5 * f(5),
    reach: pos === 'KL' ? 1.25 : 1,
    gk: pos === 'KL' ? 0.7 + 0.6 * f(4) : 0,
  };
}

function botStats(level, rnd) {
  const st = [];
  for (let i = 0; i < 6; i++) st.push(clamp(Math.round(level + (rnd() - 0.5) * 14), 35, 95));
  return st;
}

module.exports = {
  growCard, START_OVR_MAX,
  KEYS, LABELS, FULL, WEIGHTS, STYLES, TIERS, MAX_LEVEL, GP_PER_LEVEL, STAT_MAX, labelsFor, fullLabelsFor, overall, tierOf, makeStats, sanitizeLook,
  makeCard, xpNeed, addXp, upCost, applyUpgrade, passReward, PASS_ITEMS, claimable, claimPass, cardView, marketValue, derive, botStats,
};

};
