const MSG_INPUT = 1, MSG_SNAP = 2;
const HEAD = 14, PBYTES = 10;

// konum: 0.04 birim hassasiyet, -80..2540 aralığı (11v11 sahası 2415 genişliğe ulaşır)
const qpos = (v) => { v = Math.round((v + 80) * 20); return v < 0 ? 0 : v > 65535 ? 65535 : v; };
