const qv8 = (v) => { v = Math.round(v / 3); return v < -127 ? -127 : v > 127 ? 127 : v; };
const qv16 = (v) => { v = Math.round(v * 2); return v < -32767 ? -32767 : v > 32767 ? 32767 : v; };
