  u[4] = Math.round(Math.max(-1, Math.min(1, ay)) * 127) & 255;
  u[5] = btn & 31;
  u[6] = aa & 255; u[7] = am & 255; u[8] = fl & 255;       // pas yönü (0-255), kaydırma gücü (0-255), bayraklar (1 = havadan şut)
  return u;
