        const cur = m.cur === 'd' ? 'd' : 'g', price = cur === 'g' ? PACK_GOLD : PACK_GEMS, k = cur === 'g' ? 'gold' : 'gems';
        if ((u[k] || 0) < price) return fail(cur === 'g' ? 'Yeterli Altının yok (' + PACK_GOLD + ' Altın).' : 'Yeterli Elmasın yok (' + PACK_GEMS + ' Elmas).');
        u[k] -= price;
