        if (this.roleOf(c, u.name) === 'M') return fail('Duyuruyu yalnızca başkan ve subaylar yönetebilir.');
        const a = c.ann || (c.ann = []);
        if (m.t === 'ann.del') { const i = a.findIndex((x) => x.id === Number(m.id)); if (i < 0) return fail('Duyuru bulunamadı.'); a.splice(i, 1); }
        else {
          const text = String(m.text || '').replace(/[\u0000-\u001f\u007f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, ANN_LEN);
          if (!text) return fail('Duyuru boş olamaz.');
          if (m.t === 'ann.edit') { const x = a.find((y) => y.id === Number(m.id)); if (!x) return fail('Duyuru bulunamadı.'); x.text = text; x.ed = u.name; x.at = this.now(); }
          else { a.unshift({ id: this.now(), text, by: u.name, at: this.now() }); if (a.length > ANN_MAX) a.length = ANN_MAX; }
        }
