    const closed = s.no;
    for (const u of st.users.values()) {
      if (!u.card) continue;
      const i = top.findIndex((x) => x.name === u.name);
      if (u.mmr > 0) u.mmr = Math.round(u.mmr * SEASON_KEEP);
      st.putUser(u);
      if (i >= 0) { const rw = i < 3 ? SEASON_REWARDS[i] : SEASON_REST; this.notify(u, 'Sezon ' + closed + ' bitti! ' + (i + 1) + '. oldun: +' + rw.gold + ' Altın, +' + rw.gems + ' Elmas ve Kozmetik Paketi.', 'gold', 'season'); }
      else if (u.stats && u.stats.m) this.notify(u, 'Sezon ' + closed + ' bitti. Yeni sezon başladı, kupaların yarıya indi.', '', 'season');
    }
    s.no++; s.start = t; s.end = t + s.len;
    st.putDoc('sys', 'season', s);
